const FIELDS={name:['student name','student','name','full name','trainee','trainee name','student full name','pilot','client','customer','member name'],first:['first name','firstname','given name','given names','forename','preferred name'],last:['last name','lastname','surname','family name'],studentId:['student id','student no','student number','student num','studentid','arn','aviation reference number','member id','client id','student code','casa arn'],course:['course','program','programme','course name','licence','license','enrolment','enrollment'],instructor:['instructor','instructor name','flight instructor','supervisor','trainer','instructor full name'],start:['start date','course start','course start date','commencement','commencement date','commenced','enrolment date','enrollment date','start'],lesson:['lesson','lesson name','lesson no','lesson number','exercise','sequence','activity','training event','event','syllabus item','item','flight lesson','lesson code','unit','module','exam','examination','subject','theory exam'],status:['status','result','outcome','grade','competency','assessment','competent','lesson status','assessment result','score','mark','percentage'],date:['date','lesson date','flight date','completed','completion date','date completed','activity date','exam date','date of flight','date flown','assessment date'],notes:['notes','comments','comment','remarks','debrief','feedback','instructor comments','instructor notes'],att:['attendance','attended','present','attendance status','presence','present absent','attendance code','roll'],session:['session','class','period','session type','class name','activity type','type','course unit','timetable'],hours:['hours','hrs','duration','contact hours','session hours','scheduled hours']};
const LABEL={ignore:'Ignore',name:'Student name',first:'First name',last:'Last name',studentId:'Student ID / ARN',course:'Course',instructor:'Instructor',start:'Course start date',lesson:'Lesson or exam',status:'Status / result',date:'Date',notes:'Notes',att:'Attendance (present/absent)',session:'Session / class',hours:'Hours'};
const examIds=initial.exams.map(v=>v.id);
function attStatus(v){const raw=String(v??'');if(/[✓✔☑]/.test(raw))return 'Present';const t=norm(raw);if(!t)return null;if(/^(p|present|attended|yes|y|1|x|in|on time|ontime|attend)$/.test(t))return 'Present';if(/^(l|late|tardy|partial|late arrival|left early)$/.test(t)||/\blate\b/.test(t))return 'Late';if(/^(e|excused|leave|sick|medical|approved|approved absence|exc)$/.test(t)||/excused|medical|approved/.test(t))return 'Excused';if(/^(a|absent|no|n|0|nil|unexplained|ua|no show|noshow|dna)$/.test(t)||/absent|no show/.test(t))return 'Absent';if(/^present\b/.test(t))return 'Present';return null}
function lessonRef(text){const t=String(text??'').trim();if(!t||t.length>140)return null;const m=t.match(/^(?:lesson|lsn|les|l|flight|flt|ex|exercise|seq|sequence|rpl|ppl|cpl|no\.?|#)?\s*#?\s*(\d{1,2})\s*\.?\s*(a)?(?![\d/:-])\b/i);if(m){const id=m[2]?m[1]+'.a':String(Number(m[1]));if(lessonCatalogue[id])return id}const n=norm(t);if(n.length<4)return null;let best=null;for(const id in lessonCatalogue){const nm=norm(lessonCatalogue[id].name);if(nm===n)return id;if(nm.length>5&&(' '+n+' ').includes(' '+nm+' ')&&(!best||nm.length>norm(lessonCatalogue[best].name).length))best=id}return best}
function examRef(text){const n=' '+norm(text)+' ';if(n.trim().length<3)return null;let best=null;for(const id of examIds){const e=norm(id);if(n.includes(' '+e+' ')&&(!best||e.length>norm(best).length))best=id}return best}
function lessonStatus(v){const raw=String(v??'');if(/[✓✔☑]/.test(raw))return 'Completed';const t=norm(raw);if(!t)return null;if(/not yet|nyc|\bnys\b|in progress|incomplete|repeat|partial|unsat|not satisfactory|not competent|^(r|u|f|fail|failed|no|n)$/.test(t))return 'In progress';if(/^(c|comp|completed?|competent|s|sat|satisfactory|pass|passed|p|yes|y|done|ok|true|x|achieved|flown|signed off|cleared)$/.test(t)||/\b(competent|completed?|satisfactory|passed|achieved|signed off)\b/.test(t))return 'Completed';if(/not started|not attempted/.test(t))return 'Not started';return null}
function examStatus(v){const raw=String(v??'').trim();const pct=raw.match(/^(\d{1,3}(?:\.\d+)?)\s*%?$/);if(pct){const n=Number(pct[1]);if(n<=100)return {status:n>=70?'Passed':'Failed',note:'Score '+n+'%'}}const t=norm(raw);if(!t)return null;if(/fail|not yet|nyc|unsat|^(f|n|no)$/.test(t))return {status:'Failed'};if(/^(p|pass|passed|c|competent|s|sat|satisfactory|yes|y|achieved|completed?)$/.test(t)||/\b(pass|passed|competent|satisfactory|achieved)\b/.test(t))return {status:'Passed'};return null}
function isoDate(v){const t=String(v??'').trim();if(!t)return '';if(/^\d{4,5}(\.\d+)?$/.test(t)){const n=Number(t);if(n>20000&&n<80000)return new Date(Date.UTC(1899,11,30)+Math.floor(n)*864e5).toISOString().slice(0,10)}let m=t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');m=t.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);if(m){const y=m[3].length===2?'20'+m[3]:m[3];if(Number(m[2])<=12)return y+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0')}m=t.match(/^(\d{1,2})[\s-]([A-Za-z]{3,9})[\s-,]*(\d{4})/);if(m){const mo=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(m[2].slice(0,3).toLowerCase());if(mo>=0)return m[3]+'-'+String(mo+1).padStart(2,'0')+'-'+m[1].padStart(2,'0')}return ''}
function guessColumn(h){const n=norm(h);if(!n||/\b(birth|dob|phone|mobile|email|address|postcode|gender)\b/.test(n))return 'ignore';const hd=String(h??'').trim();if((/[\/-]/.test(hd)||/^\d{5}$/.test(hd))&&isoDate(hd))return 'D:'+isoDate(hd);for(const [f,words] of Object.entries(FIELDS))if(words.includes(n))return f;const l=lessonRef(h);if(l&&!/^\d+$/.test(n)||/^(lesson|l|ex|exercise)\s*\d/.test(n)&&l)return 'L:'+l;const e=examRef(h);if(e&&n.length<=norm(e).length+12)return 'E:'+e;if(/^\d{1,2}( a)?$/.test(n)&&lessonRef(h))return 'L:'+lessonRef(h);for(const [f,words] of Object.entries(FIELDS))if(words.some(w=>w.length>3&&(' '+n+' ').includes(' '+w+' ')))return f;return 'ignore'}
function findHeader(rows){for(let i=0;i<Math.min(rows.length,15);i++)if(isSmartFlights({rows,head:i})||isCancellations({rows,head:i}))return i;let best=0,score=-1;for(let i=0;i<Math.min(rows.length,15);i++){const g=rows[i].map(guessColumn).filter(f=>f!=='ignore');const plain=new Set(g.filter(f=>!/^[LED]:/.test(f))).size,extra=Math.min(2,g.filter(f=>/^[LED]:/.test(f)).length*0.5);if(plain+extra>score){score=plain+extra;best=i}}return best}

function matchStudent(info){const id=norm(info.studentId),nm=norm(info.name);for(const r of Object.values(R.students)){if(r.deleted)continue;if(id&&norm(r.state.studentId)===id)return r.uid}if(nm)for(const r of Object.values(R.students)){if(r.deleted)continue;const n=norm(r.state.name);if(n===nm||n&&n.split(' ').sort().join(' ')===nm.split(' ').sort().join(' '))return r.uid}return null}
