function change(map,info,source){if(info.name){const m=info.name.match(/^\s*([^,]+),\s*(.+?)\s*$/);if(m)info.name=m[2]+' '+m[1]}let c=info.studentId&&map.get('id:'+norm(info.studentId));if(!c&&info.name)c=[...map.values()].find(x=>x.key!=='target'&&x.info.name&&nameKey(x.info.name)===nameKey(info.name)&&(!info.studentId||!x.info.studentId||norm(x.info.studentId)===norm(info.studentId)));if(!c&&!info.name&&!info.studentId)c=map.get('target');if(!c){const key=info.studentId?'id:'+norm(info.studentId):info.name?'n:'+nameKey(info.name):'target';c={key,info:{},lessons:{},exams:{},att:{},sources:new Set(),replace:null};map.set(key,c)}if(info.studentId&&!map.has('id:'+norm(info.studentId)))map.set('id:'+norm(info.studentId),c);for(const [k,v] of Object.entries(info))if(v&&!c.info[k])c.info[k]=v;c.sources.add(source);return c}

// Smart "activity_report_flights" export: one row per flight, lesson named like "RPL(A) 7. Circuits (1.0 dual)".
const SMART_HOURS=['se_icus_day','se_icus_night','se_dual_day','se_dual_night','se_command_day','se_command_night','me_icus_day','me_icus_night','me_dual_day','me_dual_night','me_command_day','me_command_night','co_pilot_day','co_pilot_night'];
function isSmartFlights(t){const h=(t.rows[t.head]||[]).map(x=>String(x).trim().toLowerCase());return h.includes('occurred_at')&&h.includes('lesson')&&h.includes('owner_name')}
function smartLesson(text){const t=String(text||'').replace(/^\s*(RPL|PPL|CPL)\s*\(A\)\s*/i,'').trim();if(!/^\d/.test(t)&&!/^(RPL|PPL|CPL)/i.test(String(text||'').trim()))return null;const m=t.match(/^(\d{1,2})(?:\.?(a))?\.?\s+(.*?)\s*(\([^)]*\).*)?$/i);const byName=m?lessonRef(m[3]):lessonRef(t);if(m){const id=m[2]?m[1]+'.a':String(Number(m[1]));const cat=lessonCatalogue[id];if(cat){const a=norm(cat.name),b=norm(m[3]);if(!b||a===b||a.includes(b)||b.includes(a)||a.split(' ')[0]===b.split(' ')[0]||!byName)return id}}return byName}
